// Render plain text to a minimal, valid, multi-page PDF - no dependencies.
const esc = (s) => s.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
const text = String($input.first().json.output ?? $input.first().json.text ?? 'Empty report');

const lines = [];
for (const raw of text.split('\n')) {
  let line = raw.replace(/[^\x20-\x7e]/g, '');
  if (line === '') { lines.push(''); continue; }
  while (line.length > 92) { lines.push(line.slice(0, 92)); line = line.slice(92); }
  lines.push(line);
}
const pages = [];
for (let i = 0; i < lines.length; i += 46) pages.push(lines.slice(i, i + 46));
if (!pages.length) pages.push(['(empty)']);

const pageCount = pages.length;
const fontObj = 3 + pageCount * 2;
const objects = [];
objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
objects[2] = `<< /Type /Pages /Kids [${pages.map((_, p) => `${3 + p * 2} 0 R`).join(' ')}] /Count ${pageCount} >>`;
pages.forEach((pg, p) => {
  const contentObj = 4 + p * 2;
  objects[3 + p * 2] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${fontObj} 0 R >> >> /Contents ${contentObj} 0 R >>`;
  let stream = 'BT /F1 11 Tf 56 780 Td 16 TL\n';
  for (const line of pg) stream += `(${esc(line)}) Tj T*\n`;
  stream += 'ET';
  objects[contentObj] = `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`;
});
objects[fontObj] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';

let pdf = '%PDF-1.4\n';
const offsets = [];
for (let n = 1; n <= fontObj; n++) {
  offsets[n] = pdf.length;
  pdf += `${n} 0 obj\n${objects[n]}\nendobj\n`;
}
const xref = pdf.length;
pdf += `xref\n0 ${fontObj + 1}\n0000000000 65535 f \n`;
for (let n = 1; n <= fontObj; n++) pdf += `${String(offsets[n]).padStart(10, '0')} 00000 n \n`;
pdf += `trailer\n<< /Size ${fontObj + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;

const fileName = `weekly-report-${new Date().toISOString().slice(0, 10)}.pdf`;
const binaryData = await this.helpers.prepareBinaryData(Buffer.from(pdf, 'latin1'), fileName, 'application/pdf');
return [{ json: { fileName }, binary: { data: binaryData } }];
